$py = @'
import sqlite3, subprocess, tempfile, os
repo = r'D:\repository\skills'
head = subprocess.check_output(['git','show','HEAD:deploy-env/registry.sqlite'], cwd=repo)
tmp = os.path.join(tempfile.gettempdir(), 'ov-registry-head-check.sqlite')
with open(tmp,'wb') as f: f.write(head)
def snap(path):
    con=sqlite3.connect(path); out={}
    ts=[r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]
    for t in ts:
        cols=[r[1] for r in con.execute("PRAGMA table_info('%s')"%t)]
        rows=[tuple(r) for r in con.execute("SELECT * FROM '%s'"%t)]
        out[t]=(cols,rows)
    con.close(); return out
def tmap(cols,rows):
    return { (r[0] if r else i): dict(zip(cols,r)) for i,r in enumerate(rows) }
a=snap(tmp); b=snap(os.path.join(repo,'deploy-env','registry.sqlite'))
for t in sorted(set(a)|set(b)):
    ca,ra=a.get(t,([],[])); cb,rb=b.get(t,([],[]))
    ma=tmap(ca,ra); mb=tmap(cb,rb)
    diff={}
    for k in set(ma)&set(mb):
        for c in cb:
            if ma[k].get(c)!=mb[k].get(c): diff[c]=diff.get(c,0)+1
    added=len(set(mb)-set(ma)); removed=len(set(ma)-set(mb))
    if ca!=cb: print('SCHEMA_DIFF', t, ca, '->', cb)
    if diff or added or removed:
        print('TABLE', t, 'changed_cols=', {c:n for c,n in diff.items()}, 'added=', added, 'removed=', removed)
os.remove(tmp)
'@
